mapper.select:
SELECT balance
FROM account
WHERE account_id = #{accountId}
AND user_id = #{userId}
FOR UPDATE

mapper.update:
UPDATE account
SET balance = balance + #{amount}
WHERE account_id = #{accountId}
AND user_id = #{userId}

UPDATE account
SET balance = balance - #{amount}
WHERE account_id = #{accountId}
AND user_id = #{userId}
AND balance >= #{amount}

mapper.select:
SELECT account_id
FROM account
WHERE ex_account_id = #{exAccountId}

SELECT EXISTS (
SELECT 1 FROM account
WHERE account_id = #{accountId}
AND user_id = #{userId}
)

SELECT a.account_id AS accountId, a.account_type AS accountType, a.account_name AS accountName, fi.financial_institution_name AS institutionName, a.masked_account_number AS maskedAccountNumber, a.balance - COALESCE((SELECT SUM(mb.balance) FROM money_box mb WHERE mb.account_id = a.account_id), 0) AS balance, a.account_status AS accountStatus, a.opened_at AS openedAt, a.maturity_at AS maturityAt, a.interest_rate AS interestRate, a.monthly_payment_limit AS monthlyPaymentLimit FROM account a INNER JOIN financial_institution fi ON a.financial_institution_id = fi.financial_institution_id WHERE a.user_id = #{userId}
AND a.account_type = #{accountType}
AND NOT EXISTS ( SELECT 1 FROM goal_asset ga JOIN goal g ON ga.goal_id = g.goal_id WHERE g.user_id = #{userId} AND ga.asset_type = 'ACCOUNT' AND ga.asset_id = a.account_id )
AND NOT EXISTS ( SELECT 1 FROM goal_asset ga JOIN goal g ON ga.goal_id = g.goal_id JOIN money_box mb ON mb.money_box_id = ga.asset_id WHERE g.user_id = #{userId} AND ga.asset_type = 'MONEY_BOX' AND mb.account_id = a.account_id )
ORDER BY a.account_id
